import yaml, sys
P="/api/method/saas_core.api.v1."
paths={}
def ref(n): return {"$ref":f"#/components/schemas/{n}"}
def env(schema): return {"type":"object","required":["message"],"properties":{"message":schema}}
def page(n): return env({"type":"object","required":["items","next_cursor"],"properties":{"items":{"type":"array","items":ref(n)},"next_cursor":{"type":["string","null"]}}})
ERR={c:{"$ref":f"#/components/responses/{n}"} for c,n in {"400":"BadRequest","401":"Unauthorized","403":"Forbidden","404":"NotFound","409":"Conflict","422":"Unprocessable","429":"RateLimited","502":"BadGateway","503":"ServiceUnavailable"}.items()}
def op(name, method, opid, summary, tag, resp=None, body=None, query=None, auth=True, idem=False, paging=False, errs=("400","401","403","404"), status="200", extra=None):
    o={"operationId":opid,"summary":summary,"tags":[tag]}
    params=[]
    if paging: params+= [{"$ref":"#/components/parameters/Cursor"},{"$ref":"#/components/parameters/Limit"}]
    for q in (query or []):
        n,t=q[0],q[1]; req=len(q)>2 and q[2]
        params.append({"name":n,"in":"query","required":bool(req),"schema":t if isinstance(t,dict) else {"type":t}})
    if idem: params.append({"$ref":"#/components/parameters/IdempotencyKey"})
    if params:o["parameters"]=params
    if body:
        o["requestBody"]={"required":True,"content":{"application/json":{"schema":body if isinstance(body,dict) else ref(body)}}}
    o["security"]=[{"cookieAuth":[]},{"apiKey":[]},{"bearerAuth":[]}] if auth else []
    r={}
    r[status]={"description":"OK","content":{"application/json":{"schema":resp or env({"type":"object"})}}} if resp is not False else {"description":"No content"}
    for e in errs:
        if e in ERR:r[e]=ERR[e]
    if auth or method=="post": r["429"]=ERR["429"]
    r["default"]={"$ref":"#/components/responses/Error"}
    o["responses"]=r
    if extra:o.update(extra)
    paths.setdefault(P+name,{})[method]=o
S=lambda n:env(ref(n))
